func (c *Core) vhfOpenImpl(sp *VHFStream, inReal []float64, startIdx, optInTimePeriod int32, outBegIdx, outNBElement *int32, outReal []float64, outStride int32) RetCode {
	var today int32
	var outIdx int32
	var lookbackTotal int32
	var i int32
	var highest float64
	var lowest float64
	var sumChange float64
	var prev float64
	var tempReal float64
	if len(inReal) > IndexMax+1 {
		return OutOfRangeEndIndex
	}
	historyLen := int32(len(inReal))
	endIdx := historyLen - 1
	if optInTimePeriod == IntegerDefault {
		optInTimePeriod = 28
	} else if optInTimePeriod < 2 || optInTimePeriod > 100000 {
		return BadParam
	}
	if startIdx >= historyLen {
		*outBegIdx = 0
		*outNBElement = 0
		return InsufficientHistory
	}
	*outBegIdx = 0
	*outNBElement = 0
	lookbackTotal = c.vhfLookback(optInTimePeriod)
	if startIdx < lookbackTotal {
		startIdx = lookbackTotal
	}
	if startIdx > endIdx {
		return InsufficientHistory
	}
	outIdx = 0
	today = startIdx
	for today <= endIdx {
		highest = inReal[today]
		lowest = highest
		prev = highest
		sumChange = 0.0
		for i = optInTimePeriod; i >= 0; i -= 1 {
			tempReal = inReal[today-i]
			if i < optInTimePeriod {
				sumChange += math.Abs(tempReal - prev)
				if tempReal > highest {
					highest = tempReal
				}
				if tempReal < lowest {
					lowest = tempReal
				}
			}
			prev = tempReal
		}
		if sumChange > 0.0 {
			outReal[outIdx*outStride] = (highest - lowest) / sumChange
		} else {
			outReal[outIdx*outStride] = 0.0
		}
		outIdx += 1
		today += 1
	}
	*outBegIdx = startIdx
	*outNBElement = outIdx
	cap_i := optInTimePeriod + 1
	if cap_i < 1 || cap_i > historyLen {
		return InternalError
	}
	capWin_i_inReal := make([]float64, cap_i)
	copy(capWin_i_inReal, inReal[historyLen-cap_i:historyLen])
	sp.optInTimePeriod = optInTimePeriod
	sp.winPos_i = 0
	sp.winCap_i = cap_i
	sp.win_i_inReal = capWin_i_inReal
	sp.cur_outReal = outReal[(*outNBElement-1)*outStride]
	return Success
}

